        if cnt > 0:
            counts[c] = cnt
            cols.append(c)

    target = w - 1  # default: far right

    # Heuristic 1: if there is a 1,2,3 progression on columns spaced by 2,
    # place 2 between the last two columns of that progression.
    found = False
    for c in cols:
        if counts.get(c, 0) == 1 and counts.get(c + 2, 0) == 2 and counts.get(c + 4, 0) == 3:
            target = c + 3
            found = True
            break

    # Heuristic 2: if the two rightmost occupied columns are spaced by 2 and
    # have heights 1 and 3, place 2 between them.
    if not found and len(cols) >= 2:
        c1, c2 = cols[-2], cols[-1]
        if c2 - c1 == 2 and counts.get(c1, 0) == 1 and counts.get(c2, 0) == 3:
            target = c1 + 1
            found = True

    # Place the 2 on the bottom row
    out[h - 1][target] = 2

    # If placed at the far right, add the 4-cross marker near the top-right
    if target == w - 1 and h >= 3 and w >= 3:
